mapper.select:
SELECT j.ID AS id, j.INSTANCE_ID AS instanceId, j.NODE_ID AS nodeId, j.JOB_TYPE AS jobType, j.DUE_TIME_MS AS dueTimeMs, j.JOB_STATUS AS jobStatus, j.RETRY_COUNT AS retryCount, j.MAX_RETRY AS maxRetry, j.LAST_ERROR AS lastError, j.PAYLOAD_JSON AS payloadJson, j.ENV_CODE AS envCode, j.DELETED AS deleted, j.CREATE_USER AS createUser, j.CREATE_TIME AS createTime, j.UPDATE_USER AS updateUser, j.UPDATE_TIME AS updateTime FROM AST_FLOW_TIMER_JOB j WHERE (j.DELETED = 0 OR j.DELETED IS NULL)
AND j.INSTANCE_ID = #{req.instanceId}
AND j.NODE_ID LIKE CONCAT('%', #{req.nodeId}, '%')
AND j.JOB_TYPE = #{req.jobType}
AND j.JOB_STATUS = #{req.jobStatus}
AND j.ENV_CODE = #{req.envCode}
ORDER BY j.UPDATE_TIME DESC, j.ID DESC
